 $('play-again').onclick=()=>{state.profile.level=r.level;newRun(r.mode);};$('result-exit').onclick=()=>navigate('arcade');if($('result-wrong'))$('result-wrong').onclick=()=>{state.profile.level=r.level;filter={section:'',mode:'all',search:'',source:'catalog',exam:''};queue=wrong.map(x=>questionMap.get(x.qid));qi=0;selected=0;submitted=false;answerXP=null;readerPage=0;navigate('practice');};bindKnowledge();
