function matches(q){const h=historyFor(q);return q.level===currentLevel()&&(!filter.section||q.section===filter.section)&&(!filter.exam||examFor(q)===filter.exam)&&(filter.source==='all'||(filter.source==='catalog'?q.type!=='custom':q.type===filter.source))&&(!filter.search||(/^\d+$/.test(filter.search.trim())?q.number===Number(filter.search.trim()):JSON.stringify([q.knowledge,cardsFor(q).map(c=>({term:c.term,entry:c.entries.find(e=>e.qid===q.id)})),q.searchText,q.prompt,q.number,q.exam]).toLowerCase().includes(filter.search.toLowerCase())))&&({all:true,new:!h.first,correct:h.last?.answer===q.answer,wrong:h.last&&h.last.answer!==q.answer,review:h.review,everWrong:h.everWrong,star:state.stars.includes(q.id)})[filter.mode];}
