 if(run){$('pause-run').onclick=()=>navigate('arcade');$('challenge-next').onclick=nextChallenge;}else{$('prev').onclick=()=>move(-1);$('next').onclick=()=>move(1);}$('star').onclick=()=>{state.stars=state.stars.includes(q.id)?state.stars.filter(x=>x!==q.id):[...state.stars,q.id];persist();drawQuestion();};
